using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools ---
var notebook = new Notebook();
var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.WriteLine($"  🔍 Searching: {query}");
            return WebSearch.SearchAsync(query);
        },
        "search_web",
        "Search the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("Short title for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            Console.WriteLine($"  📝 Note saved: {title}");
            notebook.Add(title, content);
            return $"Note '{title}' saved successfully.";
        },
        "take_note",
        "Save a research note. Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () =>
        {
            Console.WriteLine("  📖 Reading all notes...");
            return notebook.GetAll();
        },
        "read_notes",
        "Read all previously saved research notes."),
};

// --- Agent setup ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic, you must:
        1. Search the web for relevant information (make multiple searches to cover different angles).
        2. Take notes on the most important findings as you go.
        3. Read your notes and produce a well-structured summary of your research.

        Always search at least 3 different queries to get broad coverage.
        Always take notes before writing the final summary.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run ---
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software engineering productivity";

Console.WriteLine($"🔬 Researching: {topic}\n");

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary:\n\n{topic}",
    session: null,
    options: new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    }));

Console.WriteLine("\n════════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("════════════════════════════════════════\n");
Console.WriteLine(response.Text);

// --- Supporting types ---

/// <summary>Simulated web search that returns canned results for demonstration.</summary>
static class WebSearch
{
    public static Task<string> SearchAsync(string query)
    {
        var results = new StringBuilder();
        results.AppendLine($"Search results for: \"{query}\"\n");

        // Produce deterministic but query-relevant simulated results
        var hash = Math.Abs(query.GetHashCode());
        string[] snippets =
        [
            $"A 2024 study found that {query} is a rapidly evolving area with significant industry interest. " +
            "Researchers report measurable improvements in developer velocity when AI-assisted tools are adopted.",

            $"According to recent surveys, organizations investing in {query} have seen 20-40% productivity gains, " +
            "though outcomes vary by team maturity and domain complexity.",

            $"Experts caution that while {query} shows promise, challenges remain around accuracy, security, and " +
            "the need for human oversight. Best practices include iterative validation and clear governance.",
        ];

        for (var i = 0; i < snippets.Length; i++)
        {
            results.AppendLine($"[{i + 1}] {snippets[i]}");
        }

        return Task.FromResult(results.ToString());
    }
}

/// <summary>Simple in-memory notebook for the agent to store research notes.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public string GetAll()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"--- Note {i + 1}: {_notes[i].Title} ---");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

